import SwiftUI
struct SectionEditorView: View { @Binding var section: ResumeSection; var onSave: ()->Void; @Environment(\.dismiss) private var dismiss; var body: some View { NavigationStack { VStack(spacing:0){ TextField("Section title",text:$section.title).font(.system(size:28,weight:.bold)).padding(); List { ForEach($section.fields){$field in FieldRowView(field:$field){section.fields.removeAll{$0.id==field.id}}}; Button{section.fields.append(ResumeField(label:"New Field",value:"Add detail"))} label:{Label("Add Field",systemImage:"plus.circle.fill")} } }.background(DS.ColorToken.background).toolbar{ToolbarItem(placement:.confirmationAction){Button("Done"){onSave(); dismiss()}}} }.presentationDetents([.medium,.large]) } }
